 "files": {
  "agents/caseworker_assistant.agf.yaml": "schema_version: \"1.0.0\"\n\nmetadata:\n  id: caseworker_assistant\n  name: Caseworker Assistant\n  version: \"0.1.0\"\n  description: Drafts eligibility summaries for a caseworker to review\n  data_classification: restricted\n\ninterface:\n  input:\n    type: string\n    description: Intake notes for a single case\n  output:\n    type: string\n    description: A draft summary. Never a determination.\n\nconstraints:\n  tighten_only_invariant: true\n  budget:\n    max_token_usage: 25000\n    max_duration_seconds: 120\n  limits:\n    max_llm_calls: 8\n    max_tool_calls: 12\n    max_delegation_depth: 0\n  governance_policies:\n    - policy_ref: agency.privacy.pii-redaction-v1\n      required: true\n\naction_space:\n  local_tools:\n    - alias: read_client_file\n      description: Read-only, scoped to one case ID\n    - alias: calculate_income_threshold\n      description: Deterministic calculator, no LLM involved\n    - alias: draft_determination_letter\n      description: Drafts text only. Cannot send or commit.\n      approval:\n        message_template: \"Approve this draft letter before it goes anywhere?\"\n\nexecution_policy:\n  id: agf.react\n  config:\n    instructions: |\n      Summarize the intake notes. Use tools for anything numeric.\n      If the data is missing or contradictory, say so and stop.\n    model: your-model-here\n    max_steps: 8\n",
  "policy/org-baseline.yaml": "# Org-level baseline. Always applied by the runtime, on top of whatever the agent declares.\n# This is the toy's own format, NOT the Microsoft Agent Governance Toolkit's policy syntax.\n# Rules here can only add restrictions. An agent file can never loosen them.\nname: org-baseline\ndeny_tools:\n  - write_record\n  - delete_client\n  - approve_payout\n  - send_letter\napproval_tools: []\nscope:\n  # A tool argument that must equal the case the session was opened for.\n  read_client_file:\n    arg: case_id\n",
  "policy/agency.privacy.pii-redaction-v1.yaml": "# Resolved from the agent file's constraints.governance_policies[].policy_ref.\n# The agent file marks this policy required: true, so if this file is missing\n# the runtime refuses to start the agent (fail closed).\nname: agency.privacy.pii-redaction-v1\nredact:\n  SSN: '\\b\\d{3}-\\d{2}-\\d{4}\\b'\n  PHONE: '\\b\\d{3}[-.]\\d{3}[-.]\\d{4}\\b'\n  DOB: '\\b(?:0?[1-9]|1[0-2])/(?:0?[1-9]|[12]\\d|3[01])/(?:19|20)\\d{2}\\b'\n"
 }
